])

# Try different transformations and see what creates a cleaner pattern
def color_swap(grid):
    return 1 - grid

def rotate_90(grid):
    return np.rot90(grid, k=-1)

def rotate_180(grid):
    return np.rot90(grid, k=2)

def flip_horizontal(grid):
    return np.fliplr(grid)

def flip_vertical(grid):
    return np.flipud(grid)

