# Look at 2x2 patterns
print("Examining 2x2 patterns...")
for r in range(12):
    for c in range(12):
        block = input_grid[r:r+2, c:c+2]
        key = tuple(map(tuple, block.tolist()))
        if key not in [1,2,3,4,5,7,8,9,11,12,13]:  # Exclude very sparse or all-1s patterns
            pass

# Count types of 2x2 blocks
from collections import Counter
block_counts = Counter()
for r in range(12):
    for c in range(12):
        block = tuple(input_grid[r][c:c+2].tolist()) + tuple(input_grid[r+1][c:c+2].tolist())
        block_counts[block] += 1

# Get the most common block types
sorted_blocks = sorted(block_counts.items(), key=lambda x: x[1], reverse=True)[:20]
print("Most common 2x2 block patterns:")
for blocks, count in sorted_blocks[:10]:
    print(f"  {blocks}: {count}")

